"""Build original classroom cases and fictional evidence fixtures (stdlib only)."""
from pathlib import Path
import csv,json,statistics,html
R=Path(__file__).resolve().parent.parent
P=R/'practical-packs/worked-cases';P.mkdir(parents=True,exist_ok=True)
def write_csv(name,fields,rows):
 with (P/name).open('w',newline='',encoding='utf-8') as f:
  w=csv.writer(f);w.writerow(fields);w.writerows(rows)
def page(name,title,body):
 text=f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} · AIT worked cases</title><link rel="stylesheet" href="../style.css"><style>pre,.table-scroll{{overflow:auto}}section{{scroll-margin-top:20px}}.case-label{{border-left:4px solid #9d650e;padding:12px;background:#fff1c2}}video{{max-width:100%}}@media print{{nav,.no-print{{display:none}}}}</style></head><body><main><nav aria-label="Textbook navigation"><a href="../../index.html#home">Textbook home</a> · <a href="../index.html">Practical library</a> · <a href="index.html">Worked cases</a></nav><h1>{html.escape(title)}</h1>{body}<p class="muted">Prepared 27 October 2026. Teacher review and classroom trial remain required.</p></main></body></html>'''
 (P/name).write_text(text,encoding='utf-8')

pre=[4,4,3,3,3,2,2,2,1,1,2,3];post=[4,5,4,4,4,3,4,4,4,4,4,4]
before_times=[18,22,26,24,30,31,33,29,60,60,60,60];after_times=[15,18,20,17,22,19,25,21,28,26,24,23]
rows=[]
for i in range(12):
 for version,rating,seconds,done in [('before',pre[i],before_times[i],int(i<8)),('after',post[i],after_times[i],1)]:rows.append([f'F{i+1:02d}',version,'keyboard' if i%2==0 else 'pointer',done,seconds,rating])
write_csv('survey-responses.csv',['fictional_id','version','input_method','task_completed_without_hint','seconds_capped_at_60','ease_1_to_5'],rows)
summary={'fictional':True,'paired_participants':12,'rows':24,'before':{'completed':8,'total':12,'completion_percent':100*8/12,'mean_ease':statistics.mean(pre),'median_seconds_all_attempts':statistics.median(before_times)},'after':{'completed':12,'total':12,'completion_percent':100,'mean_ease':statistics.mean(post),'median_seconds_all_attempts':statistics.median(after_times)},'change_percentage_points':100*4/12,'limits':['Invented paired observations, not a real study','Same participants and task: practice/order effects','Small convenience group; no population generalisation','Different input groups too small for a reliable comparative claim']}
(P/'survey-analysis.json').write_text(json.dumps(summary,indent=2)+'\n',encoding='utf-8')
write_csv('observation-notes.csv',['fictional_id','version','observation','interpretation_limit'],[
 ['F09','before','Opened More twice; did not identify venue within 60 seconds','One invented observation; not a measured accessibility result'],
 ['F11','before','Looked for venue beside time; stopped at the timeout','Do not infer a visual or cognitive diagnosis'],
 ['F09','after','Read Venue Hall 2 beside the time and completed the task','Repeat exposure may contribute'],
 ['client','after','Venue must be visible on each session card; keep phone contact fallback','Fictional client priority, not universal preference']])
page('survey-revision.html','Turn evaluation evidence into a revision','''<p class="case-label"><strong>Entirely fictional teaching dataset.</strong> No participants were surveyed. IDs, ratings, times, client feedback and retest observations are invented.</p><p>Unit 4 projects · Use surveys, observations, client feedback and reflection for different questions.</p><p><a href="survey-responses.csv" download>Download 24 paired response rows</a> · <a href="observation-notes.csv" download>Observation and client notes</a> · <a href="survey-analysis.json" download>Calculated reference results</a> · <a href="prototype-before.html">Try the before prototype</a> · <a href="prototype-after.html">Try the revised prototype</a></p><section><h2>1. Define the check</h2><p>The fictional brief requires a volunteer to identify the venue for the Repair session within 45 seconds, without a hint, using their assigned input method. Twelve invented volunteers attempt the before and after versions in the same order. The timer is capped at 60 seconds for an incomplete attempt. Ease is rated 1 (very difficult) to 5 (very easy); it is not a correctness score.</p></section><section><h2>2. Work the calculation</h2><p>Before: 8/12 complete (66.7%); after: 12/12 (100%). The increase is <strong>33.3 percentage points</strong>, with four additional completions. Mean ease moves from 30/12 = <strong>2.5</strong> to 48/12 = <strong>4.0</strong>. Include denominators and scale labels. Report the change as a description of these supplied records, not a proven effect in the population.</p><p>Median times across all attempts, including timeouts, are 30.5 and 21.5 seconds. If analysing only successful attempts, state that different denominator and recompute rather than silently dropping failures.</p></section><section><h2>3. Connect evidence to a design decision</h2><p>Two supplied notes show difficulty locating the venue. The fictional client requires the venue beside each session time. Move the venue from an ambiguously labelled More disclosure to a visible, labelled field; use the same information order across cards. The revised prototype implements that change. This decision uses task evidence and a client requirement, rather than treating the average rating as a design instruction.</p></section><section><h2>4. Retest and qualify</h2><p>The after rows meet this task criterion within the model. They do not prove the design is accessible to everyone. Participants repeat the same task, so familiarity may contribute; the group is small, and the records are fictional. Run your own approved trial, keep observations separate from the supplied model, and test another session and keyboard route after revising.</p></section><section><h2>Guided practice</h2><p>Filter to keyboard users. Calculate completed/total before and after; explain why six people cannot establish general keyboard accessibility.</p><details><summary>Compare reasoning</summary><p>There are six keyboard records per version: 4/6 complete before and 6/6 after. These model results support a targeted follow-up; they do not replace keyboard, semantics, zoom or screen-reader checks.</p></details></section><section><h2>Independent transfer</h2><p>The client adds a second venue and a very long session title. Modify your copy of the revised prototype, define two acceptance checks and collect a small approved test record. Keep expected and actual results separate. Submit the CSV calculations, before/after source, client-decision note and one limitation-supported reflection.</p></section>''')
for version in ['before','after']:
 venue='<details><summary>More</summary><p>Hall 2</p></details>' if version=='before' else '<p><strong>Venue:</strong> Hall 2</p>'
 page(f'prototype-{version}.html',f'Fictional session guide: {version}',f'<p class="case-label">Teaching prototype for the supplied fictional evaluation case. The model survey is not evidence that this page was tested by real learners.</p><section><h2>Repair session</h2><p>Saturday · 10 am</p>{venue}<p>Bring a small item. Book through the centre’s approved channel.</p></section><p><a href="survey-revision.html">Return to the evaluation case</a></p>')

write_csv('source-register.csv',['source_id','fictional_author','document_date','revision','claim','status','decision'],[
 ['S1','Centre coordinator','2026-10-20','1','Repair session: Hall 1, 10 am','Superseded','Do not publish without comparing revision 2'],
 ['S2','Centre coordinator','2026-10-26','2','Repair session: Hall 2, 10 am','Current approved schedule for this fictional case','Use for venue and time'],
 ['S3','Volunteer repost','2026-10-27','unknown','Repair session: Hall 1, 10 am','Newer post copying old facts','Newest timestamp does not make venue correct'],
 ['S4','Equipment supplier','2026-10-25','1','Our tablet makes all volunteers twice as fast','Marketing; no method supplied','Do not present as measured productivity'],
 ['S5','Centre coordinator','2026-10-27','3','Proposed move to Hall 3','Unapproved draft','Seek confirmation; revision number alone is insufficient']])
page('source-checking.html','Check a claim against its evidence','''<p class="case-label">The centre, documents, dates and claims in this case are fictional.</p><p>Unit 4 managing data · <a href="source-register.csv" download>Download the five-source register</a>.</p><section><h2>Question and evidence</h2><p>You must publish the venue and start time. S1 is an older approved schedule naming Hall 1. S2 is the current approved revision naming Hall 2 at 10 am. S3 is a newer volunteer repost retaining Hall 1. S4 is a supplier’s unsupported productivity claim. S5 has the highest revision number but is an unapproved draft proposing Hall 3.</p></section><section><h2>Worked decision</h2><p>Publish <strong>Hall 2, 10 am</strong>, citing S2 and recording the approval status and check date. Currency includes whether a document has been superseded, not just its timestamp. Trace S3 back to its source: it repeats stale information. Keep S5 out of approved public content until the coordinator confirms it. Neither a professional layout nor HTTPS verifies the venue.</p><p>For S4, record who benefits from the claim, missing comparison conditions and absent measurement method. Ask for workload, device versions, participant selection and raw results. The source is verifiable as a supplier statement; that does not make the productivity claim accurate.</p></section><section><h2>Guided practice</h2><p>Which is more suitable evidence for the venue: the latest repost or the current approved schedule? Explain using authorship, original evidence and status, not a general rule that official sources are always right.</p><details><summary>Compare reasoning</summary><p>S2 is directly responsible for this case’s venue decision and is approved. S3 is later but derivative and inconsistent. If two approved sources conflict, pause and resolve the discrepancy rather than selecting by appearance.</p></details></section><section><h2>Independent transfer</h2><p>The coordinator approves S5. Update the publication decision and source log, list affected outputs and specify how you will check that the stale venue has been removed. Keep the previous decision as a versioned record. Then assess one real teacher-approved claim using two primary sources; record access/publication dates and what remains unverified.</p></section>''')

page('mobile-trend.html','Compare a documented mobile-device trend','''<p>Unit 3 hardware · Historical comparison of the Wi-Fi 11-inch iPad Pro introduced in 2022 and the Wi-Fi 11-inch M4 model introduced in 2024. This is a bounded trend case, not a claim that either is the latest or a purchase recommendation.</p><p class="case-label">Source check: 27 October 2026. Review before reuse and by 27 April 2027. The client brief below is fictional; listed specifications come from Apple.</p><section><h2>Evidence before ranking</h2><div class="table-scroll" tabindex="0" role="region" aria-label="Device comparison"><table><thead><tr><th>Comparable property</th><th>2022 Wi-Fi</th><th>2024 Wi-Fi M4</th></tr></thead><tbody><tr><td>Mass, device only</td><td>466 g</td><td>444 g</td></tr><tr><td>Thickness</td><td>5.9 mm</td><td>5.3 mm</td></tr><tr><td>Display technology</td><td>IPS LCD</td><td>Tandem OLED</td></tr><tr><td>Maximum stated SDR brightness</td><td>600 nits</td><td>1000 nits</td></tr><tr><td>Named pen compatibility</td><td>Apple Pencil 2nd generation / USB-C</td><td>Apple Pencil Pro / USB-C</td></tr></tbody></table></div><p>Primary specifications: <a href="https://support.apple.com/en-us/111842">Apple 2022 model</a> and <a href="https://support.apple.com/en-us/119892">Apple 2024 model</a>. Model introduction years are given on those pages; page revision dates are not treated as introduction dates. Compare Wi-Fi with Wi-Fi, and SDR with SDR. HDR peak brightness is a different condition.</p></section><section><h2>Worked client judgement</h2><p>A fictional festival team needs a readable offline schedule during a four-hour walking shift and already owns second-generation Pencils. The later model is 22 g lighter, about 4.7% of 466 g, and has a higher stated SDR brightness limit. Those changes may help carrying and viewing. They do not establish outdoor readability, four-hour runtime or supported offline behaviour.</p><p>The owned second-generation Pencil is not listed as compatible with the M4 model; account for accessories rather than assuming a newer device meets the workflow. Run a representative offline schedule, glare and battery trial, check the required app/OS version and obtain actual costs. Keep the decision conditional while those facts are unknown.</p></section><section><h2>Guided practice</h2><p>Why is “1000 is greater than 600, therefore the later model is the correct purchase” unsupported?</p><details><summary>Compare reasoning</summary><p>Brightness is one specification with stated conditions. App support, glare, input needs, battery use, accessories and budget remain relevant. A requirement gate comes before ranking optional improvements.</p></details></section><section><h2>Independent transfer</h2><p>Compare one approved contemporary mobile device with a desktop workflow using dated primary specifications. Record essentials as pass/fail/unknown, distinguish supplier claims from measurements, and propose a task test. Include an access date and review trigger; do not use clock speed alone to rank usability.</p></section>''')

page('global-access.html','Compare historical online access restrictions','''<p>Unit 4 impacts · Historical snapshots concerning Wikipedia access. This case makes no claim about present-day availability in either jurisdiction.</p><p class="case-label">Sources checked 27 October 2026; review by 27 April 2027 and before classroom reuse. The Foundation is the affected publisher and an advocate, not a neutral measurement service.</p><section><h2>Two dated primary accounts</h2><p>In its <a href="https://wikimediafoundation.org/news/2019/05/17/wikimedia-foundation-urges-chinese-authorities-to-lift-block-of-wikipedia-in-china/">17 May 2019 statement on China</a>, Wikimedia reported a block affecting all Wikipedia language editions. This supports a dated account of the publisher’s observation and position. It does not establish today’s reachability, every network’s behaviour or the authorities’ full reasoning.</p><p>In its <a href="https://wikimediafoundation.org/news/2020/01/15/access-to-wikipedia-restored-in-turkey-after-more-than-two-and-a-half-years/">15 January 2020 statement on Turkey</a>, Wikimedia reported access restoration following the Constitutional Court’s 26 December 2019 decision. Its note says restoration varied between providers at that point. A judgment, an announcement and network restoration are different events.</p></section><section><h2>Worked comparison and consequence</h2><p>Both snapshots concern access to a whole knowledge service across language editions. The Turkey account includes a documented legal challenge and reports of restoration; the China statement describes the publisher’s opposition to a block at its publication date. The documents have different dates and purposes, so do not turn them into a current ranking of countries.</p><p>A fictional international learning provider should avoid making one external service the only route to essential instructions. Provide a permitted accessible offline/text alternative and verify delivery in intended contexts. Consider authors’ ability to contribute and learners’ access to knowledge, as well as availability. This is a continuity recommendation inferred from the case, not a legal instruction to evade restrictions.</p></section><section><h2>Guided practice</h2><p>Does the 2020 restoration announcement prove every learner in Turkey had access that day?</p><details><summary>Compare reasoning</summary><p>No. The publisher’s own qualification describes differences between providers. Record source, date and scope; a broad headline does not establish every user’s experience.</p></details></section><section><h2>Independent transfer</h2><p>Choose a teacher-approved dated access-restriction case. Compare a primary decision/authority statement with an affected party’s account, identify their interests, and separate event dates from publication dates. Explain one impact on collaboration or knowledge access, give a justified delivery response and state what the evidence cannot establish.</p></section>''')
page('index.html','Worked cases: evidence, decisions and revisions','''<p>Use the model, try a supported question, then transfer the reasoning to a new brief. Real historical facts and invented classroom data are labelled separately.</p><section><h2>Unit 3 hardware</h2><p><a class="button" href="mobile-trend.html">Mobile-device trend and client comparison</a></p><p>Dated specifications, comparable conditions, an accessory constraint and a conditional recommendation.</p></section><section><h2>Unit 4 impacts</h2><p><a class="button" href="global-access.html">Historical global access-restriction comparison</a></p><p>Primary accounts, source perspective, event/publication dates and bounded consequences.</p></section><section><h2>Unit 4 managing data</h2><p><a class="button" href="source-checking.html">Resolve conflicting source claims</a></p><p>Five fictional documents distinguish accuracy, currency, approval status and verifiability.</p></section><section><h2>Unit 4 projects</h2><p><a class="button" href="survey-revision.html">Survey evidence → revision → retest</a></p><p>Paired synthetic responses, observation notes, before/after prototypes, calculations and sampling limits.</p></section><p><a href="../worked-cases-v1.zip" download>Download the worked-case pack</a></p>''')
print('Built four worked cases, five-source register, paired synthetic survey and actual before/after prototype files.')
